package com.dormrepair.order.controller;
import com.dormrepair.common.result.*; import com.dormrepair.order.dto.*; import com.dormrepair.order.service.*; import com.dormrepair.order.vo.*;
import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/student/repair-orders") @PreAuthorize("hasRole('STUDENT')")
public class StudentRepairOrderController { private final RepairOrderQueryService queries; private final RepairOrderDetailService details; private final StudentRepairOrderCreationService creation; private final StudentRepairOrderCommandService commands; public StudentRepairOrderController(RepairOrderQueryService q,RepairOrderDetailService d,StudentRepairOrderCreationService c,StudentRepairOrderCommandService commands){queries=q;details=d;creation=c;this.commands=commands;} @GetMapping public Result<PageResult<RepairOrderListItem>> page(@ModelAttribute RepairOrderQueryRequest q){q.setWorkerId(null);return Result.success(queries.page(q));} @GetMapping("/{id}") public Result<RepairOrderDetailResponse> detail(@PathVariable Long id){return Result.success(details.getDetail(id));} @PostMapping("/check-duplicate") public Result<RepairOrderDuplicateCheckResponse> checkDuplicate(@Valid @RequestBody RepairOrderDuplicateCheckRequest r){return Result.success(creation.checkDuplicate(r));} @PostMapping public Result<CreateRepairOrderResponse> create(@Valid @RequestBody CreateRepairOrderRequest r){return Result.success(creation.create(r));} @PostMapping("/{id}/confirm") public Result<Void> confirm(@PathVariable Long id){commands.confirm(id);return Result.success();} @PostMapping("/{id}/evaluation") public Result<Void> evaluate(@PathVariable Long id,@Valid @RequestBody CreateRepairEvaluationRequest r){commands.evaluate(id,r);return Result.success();} @PostMapping("/{id}/rework") public Result<Void> rework(@PathVariable Long id,@Valid @RequestBody CreateReworkRequest r){commands.rework(id,r);return Result.success();} }
